function _baseURI() internal view override returns (string memory) {
return baseURI;
}

function editBaseUri(string memory newUri) public onlyOwner{
baseURI = newUri;
}

function editBuyNowMultipler(uint256 newMultiplier) public onlyOwner{
buyNowMultiplier = newMultiplier;
}

function editMinBidStep(uint256 newMinBidStep) public onlyOwner{
minBidStep = newMinBidStep;
}

function editDuration(uint256 newDuration) public onlyOwner{
