address from,
address to,
uint256 tokenId
) internal virtual {}

function _afterTokenTransfer(
address from,
address to,
uint256 tokenId
) internal virtual {}
}

abstract contract ERC721URIStorage is ERC721 {
using Strings for uint256;

mapping(uint256 => string) private _tokenURIs;

function tokenURI(uint256 tokenId) public view virtual override returns (string memory) {
require(_exists(tokenId), "ERC721URIStorage: URI query for nonexistent token");

string memory _tokenURI = _tokenURIs[tokenId];
string memory base = _baseURI();

if (bytes(base).length == 0) {
return _tokenURI;
}

if (bytes(_tokenURI).length > 0) {
return string(abi.encodePacked(base, _tokenURI));
}

return super.tokenURI(tokenId);
}

function _setTokenURI(uint256 tokenId, string memory _tokenURI) internal virtual {
require(_exists(tokenId), "ERC721URIStorage: URI set of nonexistent token");
_tokenURIs[tokenId] = _tokenURI;
}

function _burn(uint256 tokenId) internal virtual override {
super._burn(tokenId);

if (bytes(_tokenURIs[tokenId]).length != 0) {
delete _tokenURIs[tokenId];
}
}
}

abstract contract Ownable is Context {
address private _owner;

event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

constructor() {
_transferOwnership(_msgSender());
}

function owner() public view virtual returns (address) {
return _owner;
}

modifier onlyOwner() {
require(owner() == _msgSender(), "Ownable: caller is not the owner");
_;
}

function renounceOwnership() public virtual onlyOwner {
_transferOwnership(address(0));
}

function transferOwnership(address newOwner) public virtual onlyOwner {
require(newOwner != address(0), "Ownable: new owner is the zero address");
_transferOwnership(newOwner);
}

function _transferOwnership(address newOwner) internal virtual {
address oldOwner = _owner;
_owner = newOwner;
emit OwnershipTransferred(oldOwner, newOwner);
}
}

library Counters {
struct Counter {

uint256 _value;
}

function current(Counter storage counter) internal view returns (uint256) {
return counter._value;
}

function increment(Counter storage counter) internal {
unchecked {
counter._value += 1;
}
}

function decrement(Counter storage counter) internal {
uint256 value = counter._value;
require(value > 0, "Counter: decrement overflow");
unchecked {
counter._value = value - 1;
}
}

function reset(Counter storage counter) internal {
counter._value = 0;
}
}

contract FlippazOne is ERC721, ERC721URIStorage, Ownable {
using Counters for Counters.Counter;

Counters.Counter private _tokenIdCounter;

string public baseURI;
address public proxyRegistryAddress;

uint256 public constant MAX_SUPPLY = 1;
uint256 public minBidStep = 0.25 ether;

uint256 public constant buyNowPrice = 15 ether;
uint256 public constant buyNowPriceUntilBid = 14.75 ether;
uint256 public buyNowMultiplier = 20;
bool public boughtNow;

uint256 public auctionDuration = 24 hours;
bool public auctionStarted;
uint256 public auctionStartTimestamp;
bool public auctionEnded;
uint256 public auctionEndTimestamp;

uint256 public highestBid = 0.9 ether;
address public highestBidder;
uint256 public totalSupply = 0;

mapping(address => uint) public bids;
mapping(address => bool) public projectProxy;

mapping(address => bool) public hasAddressBidded;
address[] bidAdresses;
uint256 totalBidAddresses;

constructor() ERC721("FlippazOne", "FlippazOne") {
proxyRegistryAddress = 0xa5409ec958C83C3f309868babACA7c86DCB077c1;
baseURI = "ipfs:
}

function _baseURI() internal view override returns (string memory) {
return baseURI;
}

function editBaseUri(string memory newUri) public onlyOwner{
baseURI = newUri;
}

function editBuyNowMultipler(uint256 newMultiplier) public onlyOwner{
buyNowMultiplier = newMultiplier;
}

function editMinBidStep(uint256 newMinBidStep) public onlyOwner{
minBidStep = newMinBidStep;
}

function editDuration(uint256 newDuration) public onlyOwner{
require(auctionStarted, "Auction has not yet been started");
auctionEndTimestamp = auctionStartTimestamp + newDuration;
auctionDuration = newDuration;
}

function isAuctionActive() public view returns(bool){
if (auctionStarted){
if (!auctionEnded){
return block.timestamp < auctionEndTimestamp;
}
}
return false;
}

function startAuction() public onlyOwner{
require(auctionStarted == false, "Auction is already started");
auctionStarted = true;
auctionStartTimestamp = block.timestamp;
auctionEndTimestamp = block.timestamp + auctionDuration;
}

function getBidderPaidAmount(address bidder) public view returns(uint256){
return bids[bidder];
}

function getBidderByIndex(uint256 bidderIndex) public view returns(address){
return bidAdresses[bidderIndex];
}

function bid() public payable {
require(auctionStarted, "Auction has not yet started");
require(!auctionEnded, "Auction has been finished");
require(!boughtNow, "Auction has been finished");
require(block.timestamp < auctionEndTimestamp, "Auction has been finished");

uint256 newBid = bids[_msgSender()] + msg.value;
require(newBid >= highestBid + minBidStep, "Bid must be at least 0.25 ETH higher than the highest bid");

bids[_msgSender()] += msg.value;
highestBid = newBid;
highestBidder = _msgSender();

if (!hasAddressBidded[_msgSender()]){
hasAddressBidded[_msgSender()] = true;
totalBidAddresses++;
bidAdresses.push(_msgSender());
}

}

function isBuyNowActive() public view returns(bool){
if (auctionStarted){
if (!auctionEnded){
if (!boughtNow){
if (block.timestamp < auctionEndTimestamp){
return true;
}
}
}
}
return false;
}

function getBuyNowPrice() public view returns(uint256){
if (highestBid < buyNowPriceUntilBid){
return buyNowPrice;
} else {
uint256 newBuyNowPrice = highestBid * buyNowMultiplier / 10;
return newBuyNowPrice;
}
}

function buyNow() public payable {
require(auctionStarted, "Auction has not yet started");
require(!auctionEnded, "Auction has been finished");
require(block.timestamp < auctionEndTimestamp, "Auction has been finished");
require(!boughtNow, "Sorry! Somebody already used BUY NOW button");
uint256 currentBuyPrice = getBuyNowPrice();
require(msg.value == currentBuyPrice - bids[_msgSender()], "Invalid funds provided");

highestBid = currentBuyPrice;
highestBidder = _msgSender();

uint256 tokenId = _tokenIdCounter.current();
_tokenIdCounter.increment();
_mint(_msgSender(), tokenId);
boughtNow = true;
auctionEnded = true;
totalSupply = 1;
}

function endAuction() public {
require(auctionStarted, "Auction has not yet started");
require(!auctionEnded, "You cannot end the action again");
require(block.timestamp >= auctionEndTimestamp, "Auction duration has not yet elapsed");
uint256 tokenId = _tokenIdCounter.current();
_tokenIdCounter.increment();

if (highestBidder != address(0)){
_safeMint(highestBidder, tokenId);
} else {
_safeMint(owner(), tokenId);
}
totalSupply = 1;
auctionEnded = true;
}

function refundBids() public {
require(auctionEnded, "Please end the auction firstly");
for (uint256 i = 0; i < totalBidAddresses; i++){
uint256 addressTotalBid = bids[bidAdresses[i]];
if ((addressTotalBid > 0) && (bidAdresses[i] != highestBidder)){
(bool success, ) = bidAdresses[i].call{value: addressTotalBid}("");
bids[bidAdresses[i]] = 0;
}
}
}

function burn(uint256 tokenId) public {
require(_isApprovedOrOwner(_msgSender(), tokenId), "Not approved to burn.");
_burn(tokenId);
}

function ownerWithdraw() public {
require(auctionEnded || block.timestamp > auctionEndTimestamp, "Cannot withdraw until auction is ended");
(bool success, ) = owner().call{value: highestBid}("");
require(success, "Failed to withdraw funds.");
}

function ownerWithdrawTo(address toAddress) public {
require(auctionEnded || block.timestamp > auctionEndTimestamp, "Cannot withdraw until auction is ended");
(bool success, ) = toAddress.call{value: highestBid}("");
require(success, "Failed to withdraw funds.");
}

function ownerWithdrawAll() public {
(bool success, ) = owner().call{value: address(this).balance}("");
require(success, "Failed to withdraw funds.");
}

function ownerWithdrawAllTo(address toAddress) public {
(bool success, ) = toAddress.call{value: address(this).balance}("");
require(success, "Failed to withdraw funds.");
}

function bidderWithdraw() public {
uint256 totalBid = getBidderPaidAmount(_msgSender());
require(totalBid > 0, "Nothing to withdraw");
require(highestBidder != _msgSender(), "You cannot withdraw as your bid is the highest bid");
(bool success, ) = _msgSender().call{value: totalBid}("");
require(success, "Failed to withdraw funds.");
bids[_msgSender()] = 0;
}

function _burn(uint256 tokenId) internal override(ERC721, ERC721URIStorage) {
super._burn(tokenId);
}

function tokenURI(uint256 tokenId)
public
view
override(ERC721, ERC721URIStorage)
returns (string memory)
{
require(_exists(tokenId), "Token does not exist");
return _baseURI();
}

function isApprovedForAll(address _owner, address operator) public view override(ERC721) returns (bool) {
OpenSeaProxyRegistry proxyRegistry = OpenSeaProxyRegistry(proxyRegistryAddress);
if (address(proxyRegistry.proxies(_owner)) == operator || projectProxy[operator]) return true;
return super.isApprovedForAll(_owner, operator);
}
}

contract OwnableDelegateProxy { }

contract OpenSeaProxyRegistry {
mapping(address => OwnableDelegateProxy) public proxies;
}
